/*
 * newlib system calls for the board.
 *
 *   stdout/stderr  -> ST-LINK virtual COM port (\n becomes \r\n)
 *   malloc         -> heap between the end of .bss and the stack
 *   time()         -> wall clock set by the lab (pal_wall_ms)
 *   fopen("r")     -> a tiny read-only file system compiled into flash
 *                     (romfs_data.c, generated by CMake). Lookup is by base
 *                     name, so "--ca servers/mosquitto/certs/ca.crt" and
 *                     "--ca ca.crt" both find the embedded lab CA.
 * Writing files fails cleanly (bench_write_csv just reports it).
 */

#include <errno.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/times.h>

#include "board.h"
#include "pal.h"
#include "romfs.h"

#undef errno
extern int errno;

#define FD_FIRST 3
#define FD_MAX 4

static struct {
    const romfs_file_t *f;
    size_t pos;
} fds[FD_MAX];

static const char *base_name(const char *p)
{
    const char *b = p;
    for (; *p; p++) {
        if (*p == '/' || *p == '\\') {
            b = p + 1;
        }
    }
    return b;
}

int _open(const char *path, int flags, int mode)
{
    (void)mode;
    if ((flags & O_ACCMODE) != O_RDONLY) {
        errno = EROFS;
        return -1;
    }
    for (const romfs_file_t *f = romfs_files; f->name; f++) {
        if (strcmp(f->name, base_name(path)) == 0) {
            for (int i = 0; i < FD_MAX; i++) {
                if (fds[i].f == NULL) {
                    fds[i].f = f;
                    fds[i].pos = 0;
                    return FD_FIRST + i;
                }
            }
            errno = EMFILE;
            return -1;
        }
    }
    errno = ENOENT;
    return -1;
}

static int slot(int fd)
{
    int i = fd - FD_FIRST;
    return (i >= 0 && i < FD_MAX && fds[i].f) ? i : -1;
}

int _close(int fd)
{
    int i = slot(fd);
    if (i >= 0) {
        fds[i].f = NULL;
    }
    return 0;
}

int _read(int fd, char *buf, int len)
{
    int i = slot(fd);
    size_t n;
    if (i < 0) {
        errno = EBADF;
        return -1;
    }
    n = fds[i].f->len - fds[i].pos;
    if (n > (size_t)len) {
        n = (size_t)len;
    }
    memcpy(buf, fds[i].f->data + fds[i].pos, n);
    fds[i].pos += n;
    return (int)n;
}

int _lseek(int fd, int off, int whence)
{
    int i = slot(fd);
    long p;
    if (i < 0) {
        return 0; /* stdio */
    }
    p = whence == SEEK_SET ? off : whence == SEEK_CUR ? (long)fds[i].pos + off : (long)fds[i].f->len + off;
    if (p < 0 || (size_t)p > fds[i].f->len) {
        errno = EINVAL;
        return -1;
    }
    fds[i].pos = (size_t)p;
    return (int)p;
}

int _write(int fd, const char *buf, int len)
{
    if (fd != 1 && fd != 2) {
        errno = EBADF;
        return -1;
    }
    for (int i = 0, start = 0; i <= len; i++) {
        if (i == len || buf[i] == '\n') {
            vcp_write(buf + start, (size_t)(i - start));
            if (i < len) {
                vcp_write("\r\n", 2);
            }
            start = i + 1;
        }
    }
    return len;
}

int _fstat(int fd, struct stat *st)
{
    memset(st, 0, sizeof(*st));
    st->st_mode = slot(fd) >= 0 ? S_IFREG : S_IFCHR;
    if (slot(fd) >= 0) {
        st->st_size = (off_t)fds[slot(fd)].f->len;
    }
    return 0;
}

int _isatty(int fd)
{
    return fd <= 2;
}

void *_sbrk(ptrdiff_t incr)
{
    extern uint8_t _end;           /* linker: end of .bss */
    extern uint8_t _estack;        /* linker: top of RAM */
    extern uint32_t _Min_Stack_Size;
    static uint8_t *brk;
    const uint8_t *limit = &_estack - (uint32_t)&_Min_Stack_Size;
    uint8_t *prev;

    if (brk == NULL) {
        brk = &_end;
    }
    if (brk + incr > limit) {
        errno = ENOMEM;
        return (void *)-1;
    }
    prev = brk;
    brk += incr;
    return prev;
}

int _gettimeofday(struct timeval *tv, void *tz)
{
    (void)tz;
    if (tv) {
        uint64_t ms = pal_wall_ms();
        tv->tv_sec = (time_t)(ms / 1000u);
        tv->tv_usec = (suseconds_t)((ms % 1000u) * 1000u);
    }
    return 0;
}

clock_t _times(struct tms *t)
{
    (void)t;
    return (clock_t)-1;
}

int _getpid(void)
{
    return 1;
}

int _kill(int pid, int sig)
{
    (void)pid;
    (void)sig;
    errno = EINVAL;
    return -1;
}

void _exit(int status)
{
    (void)status;
    board_reset();
}

int _unlink(const char *path)
{
    (void)path;
    errno = EROFS;
    return -1;
}

int _link(const char *a, const char *b)
{
    (void)a;
    (void)b;
    errno = EROFS;
    return -1;
}

int _stat(const char *path, struct stat *st)
{
    int fd = _open(path, O_RDONLY, 0);
    if (fd < 0) {
        return -1;
    }
    _fstat(fd, st);
    _close(fd);
    return 0;
}
